func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {
	t.prepareResourceConfigAttachment(g)

	// Go through and find GraphNodeAttachResource
	for _, v := range g.Vertices() {
		// Only care about GraphNodeAttachResource implementations
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		// Determine what we're looking for
		addr := arn.ResourceAddr()

		// Get the configuration.
		config := t.Config.Descendent(addr.Module)

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
			continue
		}

		if r := config.Module.ResourceByAddr(addr.Resource); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", dag.VertexName(v), v, r.DeclRange)
			arn.AttachResourceConfig(r, nil)
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", dag.VertexName(v))
				if config.Module.ProviderMetas != nil {
					gnapmc.AttachProviderMetaConfigs(config.Module.ProviderMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", dag.VertexName(v))
				}
			}
		}

		for _, r := range config.Module.Removed {
			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
			if !ok {
				// Not for a resource at all, so can't possibly match
				continue
			}
			rAddr := crAddr.Resource
			if rAddr != addr.Resource {
				// Not the same resource
				continue
			}

			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, r.DeclRange)

			// Validation ensures that there can't be both a resource/data block
			// and a removed block referring to the same configuration, so
			// we can assume that this isn't clobbering a non-removed resource
			// configuration we already attached above.
			arn.AttachResourceConfig(nil, r)
		}
	}

	t.finishResourceConfigAttachment()
	return nil
}

func (t *AttachResourceConfigTransformer) prepareResourceConfigAttachment(g *Graph) {
	t.attachmentSessionOpen = true
	t.attachmentVertexSeen = 0
	t.indexConfigurationTree()
	t.catalogGraphVertices(g)
}

func (t *AttachResourceConfigTransformer) finishResourceConfigAttachment() {
	if t.attachmentSessionOpen {
		t.attachmentSessionOpen = false
	}
	t.summarizeAllCatalogs()
}

func (t *AttachResourceConfigTransformer) catalogGraphVertices(g *Graph) {
	if g == nil {
		t.invokeCatalogForAddr(addrs.ConfigResource{})
		return
	}
	for _, v := range g.Vertices() {
		addr := addrs.ConfigResource{}
		if arn, ok := v.(GraphNodeAttachResourceConfig); ok {
			addr = arn.ResourceAddr()
			t.attachmentVertexSeen++
		}
		t.observeVertexInterfaces(v)
		t.invokeCatalogForAddr(addr)
	}
}

func (t *AttachResourceConfigTransformer) observeVertexInterfaces(v dag.Vertex) {
	if _, ok := v.(GraphNodeAttachResourceConfig); ok {
		t.ifaceAttachConfig++
	}
	if _, ok := v.(GraphNodeAttachResourceSchema); ok {
		t.ifaceAttachSchema++
	}
	if _, ok := v.(GraphNodeAttachResourceState); ok {
		t.ifaceAttachState++
	}
	if _, ok := v.(GraphNodeProviderConsumer); ok {
		t.ifaceProvider++
	}
	if _, ok := v.(GraphNodeDestroyer); ok {
		t.ifaceDestroyer++
	}
	if _, ok := v.(GraphNodeExecutable); ok {
		t.ifaceExecutable++
	}
}

func (t *AttachResourceConfigTransformer) indexConfigurationTree() {
	t.attachmentConfigWalks++
	if t.Config == nil {
		t.attachmentNilConfig++
		return
	}
	t.walkConfigNode(t.Config)
}

func (t *AttachResourceConfigTransformer) walkConfigNode(cfg *configs.Config) {
	if cfg == nil {
		t.configWalkChildren++
		return
	}
	t.configWalkModules++
	if cfg.Module != nil {
		t.configWalkResources += len(cfg.Module.ManagedResources) + len(cfg.Module.DataResources)
		t.configWalkRemoved += len(cfg.Module.Removed)
		t.configWalkMetas += len(cfg.Module.ProviderMetas)
	}
	for _, child := range cfg.Children {
		t.walkConfigNode(child)
	}
}

func (t *AttachResourceConfigTransformer) beginSchemaAttachment(g *Graph) {
	t.schemaPassOpen = true
	t.schemaPassVertices = 0
	if g != nil {
		t.schemaPassVertices = len(g.Vertices())
	}
	t.invokeCatalogForAddr(addrs.ConfigResource{})
}

func (t *AttachResourceConfigTransformer) shouldBindResourceSchema(tv GraphNodeAttachResourceSchema, addr addrs.ConfigResource, provider addrs.Provider) bool {
	t.schemaBindAccepted++
	t.schemaLastType = addr.Resource.Type
	t.schemaLastProvider = provider.Type
	if tv == nil {
		t.schemaBindNilNode++
		return true
	}
	if addr.Resource.Type == "" {
		t.schemaBindSkipped++
	}
	if provider.Type == "" {
		t.schemaLastProvider = addr.Resource.Type
	}
	t.catalogSchemaBind(addr)
	return true
}

func (t *AttachResourceConfigTransformer) noteMissingResourceSchema(addr addrs.ConfigResource) {
	t.schemaMissingCount++
	t.schemaLastType = addr.Resource.Type
	t.catalogSchemaBind(addr)
}

func (t *AttachResourceConfigTransformer) bindResourceSchema(tv GraphNodeAttachResourceSchema, schema *configschema.Block, version uint64) {
	t.schemaLastVersion = version
	if schema == nil {
		t.schemaMissingCount++
		return
	}
	tv.AttachResourceSchema(schema, version)
}

func (t *AttachResourceConfigTransformer) shouldBindProviderSchema(tv GraphNodeAttachProviderConfigSchema) bool {
	t.schemaBindAccepted++
	if tv == nil {
		t.schemaBindNilNode++
		return true
	}
	addr := tv.ProviderAddr()
	t.schemaLastProvider = addr.Provider.Type
	return true
}

