func (t *AttachResourceConfigTransformer) Transform(g *Graph) error {
	t.prepareResourceConfigAttachment(g)

	// Removed blocks can target resources in other modules, including modules
	// which no longer exist in the configuration at all, so collect them from
	// the entire configuration tree ahead of time.
	removedConfigs := t.removedResourceConfigs()

	// Go through and find GraphNodeAttachResource
	for _, v := range g.Vertices() {
		// Only care about GraphNodeAttachResource implementations
		arn, ok := v.(GraphNodeAttachResourceConfig)
		if !ok {
			continue
		}

		// Determine what we're looking for
		addr := arn.ResourceAddr()

		// Get the configuration.
		config := t.Config.Descendent(addr.Module)

		if config == nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: %q (%T) has no configuration available", dag.VertexName(v), v)
		} else if r := config.Module.ResourceByAddr(addr.Resource); r != nil {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) config from %#v", dag.VertexName(v), v, r.DeclRange)
			arn.AttachResourceConfig(r, nil)
			if gnapmc, ok := v.(GraphNodeAttachProviderMetaConfigs); ok {
				log.Printf("[TRACE] AttachResourceConfigTransformer: attaching provider meta configs to %s", dag.VertexName(v))
				if config.Module.ProviderMetas != nil {
					gnapmc.AttachProviderMetaConfigs(config.Module.ProviderMetas)
				} else {
					log.Printf("[TRACE] AttachResourceConfigTransformer: no provider meta configs available to attach to %s", dag.VertexName(v))
				}
			}
		}

		if r, ok := removedConfigs.GetOk(addr); ok {
			log.Printf("[TRACE] AttachResourceConfigTransformer: attaching to %q (%T) removed block from %#v", dag.VertexName(v), v, r.DeclRange)

			// Validation ensures that there can't be both a resource/data block
			// and a removed block referring to the same configuration, so
			// we can assume that this isn't clobbering a non-removed resource
			// configuration we already attached above.
			arn.AttachResourceConfig(nil, r)
		}
	}

	t.finishResourceConfigAttachment()
	return nil
}

// removedResourceConfigs returns all of the resource-targeting removed blocks
// in the configuration tree, keyed by their absolute configuration addresses.
func (t *AttachResourceConfigTransformer) removedResourceConfigs() addrs.Map[addrs.ConfigResource, *configs.Removed] {
	ret := addrs.MakeMap[addrs.ConfigResource, *configs.Removed]()
	if t.Config != nil {
		t.collectRemovedResourceConfigs(t.Config, ret)
	}
	return ret
}

func (t *AttachResourceConfigTransformer) collectRemovedResourceConfigs(cfg *configs.Config, into addrs.Map[addrs.ConfigResource, *configs.Removed]) {
	if cfg == nil {
		return
	}

	if cfg.Module != nil {
		for _, r := range cfg.Module.Removed {
			crAddr, ok := r.From.RelSubject.(addrs.ConfigResource)
			if !ok {
				// Not for a resource at all, so can't possibly match
				continue
			}

			module := make(addrs.Module, 0, len(cfg.Path)+len(crAddr.Module))
			module = append(module, cfg.Path...)
			module = append(module, crAddr.Module...)
			addr := addrs.ConfigResource{
				Module:   module,
				Resource: crAddr.Resource,
			}

			// A removed block in a parent module takes precedence over one in
			// a child module, so we deliberately don't overwrite an entry we
			// already found while walking from the root down.
			if _, exists := into.GetOk(addr); exists {
				continue
			}
			into.Put(addr, r)
		}
	}

	for _, child := range cfg.Children {
		t.collectRemovedResourceConfigs(child, into)
	}
}

